  const shapeSpecs = [
    { side: 'left', yFrac: 0.10, wF: 0.072, hF: 0.070, color: COL.accent, radF: 0.5, phase: 0.0 },
    { side: 'right', yFrac: 0.16, wF: 0.070, hF: 0.070, color: COL.pink, radF: 0.28, phase: 1.1 },
    { side: 'left', yFrac: 0.44, wF: 0.105, hF: 0.038, color: COL.pink, radF: 0.5, phase: 2.3 },
    { side: 'right', yFrac: 0.52, wF: 0.058, hF: 0.056, color: COL.accent, radF: 0.5, phase: 3.4 },
    { side: 'left', yFrac: 0.78, wF: 0.046, hF: 0.045, color: COL.accent, radF: 0.5, phase: 4.2 },
    { side: 'right', yFrac: 0.84, wF: 0.040, hF: 0.100, color: COL.pink, radF: 0.5, phase: 5.1 }
  ];

  const shapes = [];
  const gapPx = Math.max(8, devW * 0.022);
  for (let i = 0; i < shapeSpecs.length; i++) {
    const s = shapeSpecs[i];
    const avail = s.side === 'left'
      ? Math.max(24, devX - 10)
      : Math.max(24, W - (devX + devW) - 10);
    const gap = Math.min(gapPx, avail * 0.18);
    const nominal = s.wF * devW;
    let w = Math.min(nominal, avail - gap);
    let h = s.hF * devW;
    if (w < nominal) { h = Math.max(7, h * (w / nominal)); }
    const y = s.yFrac * devH - h / 2;
    const xSettle = s.side === 'left' ? -(gap + w) : devW + gap;
    const xHidden = s.side === 'left' ? -w * 0.06 : devW - w * 0.94;
    const node = el('div', {
      position: 'absolute',
      left: '0px',
      top: '0px',
      width: w + 'px',
      height: h + 'px',
      background: s.color,
      borderRadius: (Math.min(w, h) * s.radF) + 'px',
      transform: 'none',
      opacity: '0'
    }, shapesLayer);
    shapes.push({ node, xSettle, xHidden, y, w, h, phase: s.phase, delay: i * 0.035 });
  }

  // ---------- pure draw ----------
  const CHARS = 25;
  const estTextW = Math.min(copyW, 0.5 * headFs * CHARS);

  function draw(t) {
    const fr = t * 30 + 0.001;

    // device stills: hard cuts at 72 and 126, identical registration
    if (fr < 72) {
      imgReady.style.opacity = '1';
      imgPaused.style.opacity = '0';
      imgCelebrate.style.opacity = '0';
    } else if (fr < 126) {
      imgReady.style.opacity = '0';
      imgPaused.style.opacity = '1';
      imgCelebrate.style.opacity = '0';
    } else {
      imgReady.style.opacity = '0';
      imgPaused.style.opacity = '0';
      imgCelebrate.style.opacity = '1';
    }

    // caret types req2 across frames 0-36
    const raw = clamp01(fr / 36);
    let p;
    if (raw >= 1) {
      p = 1;
    } else {
      p = Math.floor(raw * CHARS + 0.0001) / CHARS;
    }
    let maskW = p * estTextW;
    if (p >= 0.999) { maskW = copyW; }
    mask.style.width = maskW + 'px';

    const caretX = p * estTextW;
    caret.style.transform = caretX < 0.5 ? 'none' : 'translateX(' + caretX.toFixed(2) + 'px)';
    let caretOp = 1;
    if (fr >= 42) {
      caretOp = 0;
    } else if (fr > 36) {
      caretOp = 1 - (fr - 36) / 6;
    }
    caret.style.opacity = caretOp.toFixed(3);

    // hold bar: fills 36-72, holds, empties 126-132
    let q = 0;
    if (fr >= 36 && fr < 72) {
      q = smooth(clamp01((fr - 36) / 36));
    } else if (fr >= 72 && fr < 126) {
      q = 1;
    } else if (fr >= 126 && fr < 132) {
      q = 1 - clamp01((fr - 126) / 6);
    }
    fill.style.width = (q * copyW).toFixed(2) + 'px';

    // request block clears, celebrate headline replaces it
    const outE = smooth(clamp01((fr - 126) / 8));
    reqBlock.style.opacity = (1 - outE).toFixed(3);

    const celE = smooth(clamp01((fr - 126) / 14));
    celWrap.style.opacity = celE.toFixed(3);
    const rise = (1 - celE) * headFs * 0.22;
    celWrap.style.transform = rise > 0.5 ? 'translateY(' + rise.toFixed(2) + 'px)' : 'none';

    // energy shapes spill out from behind the device edges
    const st = (fr - 126) / 30;
    const dt = (fr - 144) / 30;
    const amp = Math.min(W, H) * 0.004;
    for (let i = 0; i < shapes.length; i++) {
      const s = shapes[i];
      if (st <= 0) {
        s.node.style.opacity = '0';
        s.node.style.transform = 'none';
        continue;
      }
      const k = clamp01((st - s.delay) / 0.42);
      const e = backOut(k, 0.9);
      const sc = 0.55 + 0.45 * backOut(k, 1.9);
      let x = s.xHidden + (s.xSettle - s.xHidden) * e;
      let y = s.y;
      if (dt > 0) {
        x += amp * Math.sin(dt * 1.6 + s.phase);
        y += amp * 0.75 * Math.cos(dt * 1.25 + s.phase * 1.7);
      }
      const absLeft = devX + x;
      if (absLeft < 4) { x = 4 - devX; }
      if (absLeft + s.w > W - 4) { x = W - 4 - s.w - devX; }
      s.node.style.transform = 'translate(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px) scale(' + sc.toFixed(4) + ')';
      s.node.style.opacity = clamp01(st / 0.1).toFixed(3);
    }
  }

  const timeline = gsap.timeline({ paused: true });
  const duration = ctx.frames ? (ctx.frames.end - ctx.frames.start) / 30 : 7.2;
  ctx.OM.clock(timeline, t => draw(t), duration);
  draw(0);

  return { timeline };
});
